#!/bin/bash
# Uninstall script for Aptible Toolbelt
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Aptible Toolbelt..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Aptible Toolbelt if running..."
pkill -f "Aptible Toolbelt" 2>/dev/null || true

# Remove /usr/local/bin/aptible
echo "Removing /usr/local/bin/aptible..."
if [ -d "/usr/local/bin/aptible" ]; then
    rm -rf "/usr/local/bin/aptible" 2>/dev/null || true
elif [ -f "/usr/local/bin/aptible" ]; then
    rm -f "/usr/local/bin/aptible" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
